base={(0,0),(0,1),(1,2),(1,3),(2,2),(2,3)}
def norm(points):
 mi=min(x for x,y in points); mj=min(y for x,y in points)
 return frozenset((x-mi,y-mj) for x,y in points)
variants=set()
for a,b in [(1,1),(-1,1),(1,-1),(-1,-1)]:
 for swap in (False,True):
  pts=[]
